import base64, pathlib
FILES = {
    'run.py': "",
    'server/config.py': "",
    'server/hub.py': "",
}
for path, b in FILES.items():
    p = pathlib.Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(b))
    print('wrote', path, len(base64.b64decode(b)), 'bytes')
print('PART a OK')
